package com.marketbot.core

import com.marketbot.core.kalshi.FillState
import com.marketbot.core.kalshi.TopOfBook
import com.marketbot.core.kalshi.kalshiFee
import com.marketbot.core.kalshi.settlementPnl
import com.marketbot.core.strategies.longshot.Candidate
import com.marketbot.core.strategies.longshot.LongshotModel
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull

/**
 * Every function here is compared with the ORIGINAL weatherbot Python run on
 * the same inputs (core/src/test/resources/golden, generated by golden.py).
 * Exact equality where the Python is exact; 1e-12 relative otherwise.
 */
class LongshotGoldenTest {
    @Test fun `fee matches Python at every cent price and ten order sizes`() {
        for (c in goldenCases("kalshi_fee")) {
            assertClose(c["fee"].dd, kalshiFee(c["price"].dd, c["count"].i), 1e-12) { "fee ${c["price"]} x ${c["count"]}" }
        }
    }

    @Test fun `evaluate matches Python on 3000 books`() {
        for (c in goldenCases("longshot_evaluate")) {
            val q = LongshotModel.evaluate(c["ticker"].s!!, c["bid"].dd, c["ask"].dd, c["open_markets"].i, c["max_contracts"].i)
            val exp = c["quote"]
            if (exp.isNull) assertNull(q, "expected no quote for $c")
            else {
                q ?: error("expected a quote for $c")
                assertClose(exp.o()["price"].dd, q.price)
                assertEquals(exp.o()["contracts"].i, q.contracts)
                assertClose(exp.o()["edge"].dd, q.expectedEdge, 1e-12) { "edge $c" }
            }
        }
    }

    @Test fun `lot for budget matches Python`() {
        for (c in goldenCases("longshot_lot_for_budget"))
            assertEquals(c["lot"].i, LongshotModel.lotForBudget(c["budget"].dd, c["asks"].list().map { it.dd }), "$c")
    }

    @Test fun `size for budget matches Python floor division`() {
        for (c in goldenCases("longshot_size_for_budget"))
            assertEquals(c["size"].i, LongshotModel.sizeForBudget(c["price"].dd, c["budget"].dd, c["cap"].i), "$c")
        assertEquals(9.0, LongshotModel.pyFloorDiv(1.0, 0.1), "1.0 // 0.1 is 9 in Python, not floor(1.0 / 0.1) = 10")
    }

    @Test fun `collateral budget matches Python`() {
        for (c in goldenCases("longshot_collateral_budget"))
            assertClose(c["budget"].dd, LongshotModel.collateralBudget(c["cash"].dd, c["committed_live"].dd, c["committed_book"].dd, 0.75, c["portfolio_value"].d), 1e-12)
    }

    @Test fun `candidate ordering matches Python`() {
        for (c in goldenCases("longshot_order_candidates")) {
            val cands = c["candidates"].list().map { val a = it.list(); Candidate(a[0].s!!, a[1].dd, a[2].dd) }
            val ranks = c["ranks"].o().mapValues { it.value.dd }
            assertEquals(c["ordered"].list().map { it.s }, LongshotModel.orderCandidates(cands, ranks).map { it.ticker })
        }
    }

    @Test fun `top of book read matches Python`() {
        for (c in goldenCases("longshot_book")) {
            val tob = TopOfBook.of(c["payload"].o())
            assertClose(c["bid"].d, tob?.yesBid?.value) { "bid ${c["payload"]}" }
            assertClose(c["ask"].d, tob?.yesAsk?.value) { "ask ${c["payload"]}" }
        }
    }

    @Test fun `fill state matches Python`() {
        for (c in goldenCases("kalshi_fill_state")) {
            val f = FillState.of(c["order"].o())
            assertEquals(c["filled"].b, f.filled, "${c["order"]}")
            assertClose(c["n"].d, f.contracts) { "${c["order"]}" }
        }
    }

    @Test fun `paper P&L formula matches Python pnl_for`() {
        for (c in goldenCases("longshot_pnl_for"))
            assertClose(c["pnl"].dd, LongshotModel.pnlFor(c["price"].dd, c["contracts"].i, c["result"].s!!), 1e-12)
    }

    @Test fun `settlement P&L matches the exchange derivation including closed pairs`() {
        for (c in goldenCases("kalshi_settlement_pnl"))
            assertClose(c["pnl"].dd, settlementPnl(c["payload"].o()).value, 1e-12) { "${c["payload"]}" }
    }
}
